def seed_gamification(apps, schema_editor):
    level_model = apps.get_model('blog', 'GamificationLevel')
    badge_model = apps.get_model('blog', 'Badge')
    for number, title, icon, minimum_points in LEVELS:
        level_model.objects.update_or_create(
            number=number,
            defaults={
                'title': title,
                'icon': icon,
                'minimum_points': minimum_points,
            },
        )
    for slug, title, description, icon, rarity, requirement in BADGES:
        badge_model.objects.update_or_create(
            slug=slug,
            defaults={
                'title': title,
                'description': description,
                'icon': icon,
                'rarity': rarity,
                'requirement': requirement,
                'active': True,
            },
        )


def unseed_gamification(apps, schema_editor):
    apps.get_model('blog', 'Badge').objects.filter(
        slug__in=[badge[0] for badge in BADGES]
    ).delete()
    apps.get_model('blog', 'GamificationLevel').objects.filter(
        number__in=[level[0] for level in LEVELS]
    ).delete()


